ee:message.ee:set-payload:
%dw 2.0
output application/json
---
payload update{
	case .Product2Id -> vars.codigoProducto[0].ProductCode
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
var respMap = (payload.ZMF_B2B_BRF.tables.TI_RETURN  filterObject ((value, key, index) -> value.TYPE == "E" and (value.ID == "V1" or value.ID == "ZMM" or value.ID == "ZSD" or value.ID == "VP"))).*row map (v,i) ->
{
    "NUMBER": v.NUMBER,
    "MESSAGE": v.MESSAGE
}
---
[{
	"Id": vars.idOrder,
	"VM_CodigoRespuestaSAP__c": respMap.*NUMBER joinBy "-",
    "VM_DescripcionRespuestaSAP__c": respMap.*MESSAGE joinBy "//" default "Error en procesamiento, consultar con administrador"
}]
